import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.DQQHyi2x.js";const g=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),i={name:"changelog.md"};function s(n,e,l,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to Albiex Synth City will be documented in this file.</p><p>The format is based on <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><h2 id="unreleased" tabindex="-1"><a href="https://github.com/adrirubio/claude-deck/compare/v2.0.1...HEAD" target="_blank" rel="noreferrer">Unreleased</a> <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;[Unreleased]&quot;">​</a></h2><h2 id="_4-2-0-2026-11-17" tabindex="-1">[4.2.0] - 2026-11-17 <a class="header-anchor" href="#_4-2-0-2026-11-17" aria-label="Permalink to &quot;[4.2.0] - 2026-11-17&quot;">​</a></h2><p>Albiex Synth City 4.2.0 makes the factory explain itself and gives the Leader standard ways to recover. The factory now reports stuck work items, silent background failures and automatic merges that did not run. Owners can check a request before they submit it. Work items record an effort limit, and the Leader has three standard recoveries. Claude Code members can&#39;t edit files while an unread stop or hold message waits. The backend CI suite runs as four parallel shards. This release also adds the Antigravity CLI provider, but Antigravity members can&#39;t yet be launched in a team.</p><p><strong>Not in this release (planned for 4.3):</strong> live runtime checks for OpenCode 2 members; the Antigravity CLI screen fallback, wider activity classification and cross-user proof; the Mail tool-list roster badge and live notification; the access path on the remaining operator routes; CI shard rebalancing for a steady 10-minute backend check; the continuation scope check after a base update; campaign retrospectives in Insights; installation health; Agent Mail tool calls through <code>agy</code> (<a href="https://github.com/albiexai/synth-city/issues/994" target="_blank" rel="noreferrer">#994</a>); the dispatch nonce in branch names and publication URLs (<a href="https://github.com/albiexai/synth-city/issues/1000" target="_blank" rel="noreferrer">#1000</a>).</p><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Antigravity CLI members (provider <code>antigravity-cli</code>, binary <code>agy</code>), not yet launchable in a team.</strong> Synth City builds the <code>agy</code> launch and resume commands. A resume uses <code>agy --conversation &lt;id&gt; -i &lt;prompt&gt;</code> and keeps the member&#39;s bootstrap prompt. Before a team launch, Synth City adds the workspace to <code>trustedWorkspaces</code> in the agent user&#39;s Antigravity settings. Antigravity CLI appears in the provider lists, the team slot select, repository setup, Live sessions (a new session, or a resume by the exact conversation id) and the factory filters, with model and reasoning-effort options. See <a href="https://albiex.org/docs/features/harnesses" target="_blank" rel="noreferrer">Harnesses</a> (<a href="https://github.com/albiexai/synth-city/issues/734" target="_blank" rel="noreferrer">#734</a>, <a href="https://github.com/albiexai/synth-city/pull/950" target="_blank" rel="noreferrer">PR #950</a>, <a href="https://github.com/albiexai/synth-city/issues/735" target="_blank" rel="noreferrer">#735</a>, <a href="https://github.com/albiexai/synth-city/pull/954" target="_blank" rel="noreferrer">PR #954</a>, <a href="https://github.com/albiexai/synth-city/issues/952" target="_blank" rel="noreferrer">#952</a>, <a href="https://github.com/albiexai/synth-city/pull/973" target="_blank" rel="noreferrer">PR #973</a>, <a href="https://github.com/albiexai/synth-city/issues/738" target="_blank" rel="noreferrer">#738</a>, <a href="https://github.com/albiexai/synth-city/pull/989" target="_blank" rel="noreferrer">PR #989</a>, <a href="https://github.com/albiexai/synth-city/issues/981" target="_blank" rel="noreferrer">#981</a>, <a href="https://github.com/albiexai/synth-city/pull/1024" target="_blank" rel="noreferrer">PR #1024</a>).</li><li><strong>Agent Mail setup, readiness gates, read-only observation and a team guard for Antigravity CLI.</strong> <strong>Set up</strong> and <strong>Remove</strong> on the Antigravity CLI harness page manage the Mail server (under the key <code>synth-city-mail</code>, so every tool name stays valid for <code>agy</code>) and three hook groups. For a team member, the hook denies <code>agy</code>&#39;s question tool, even when Synth City can&#39;t be reached. Team readiness stays blocked for two reasons. First, Mail tool calls through <code>agy</code> aren&#39;t proven: in an isolated run, <code>call_mcp_tool</code> was not declared to the model. Second, the agent user must complete <code>agy</code>&#39;s own onboarding; Synth City reads that signal read-only and never accepts the terms. The observer classifies only the activity shapes seen on <code>agy</code> 1.5.9 and reports everything else as unknown. An open question it observes is escalated to the Supervisor once. The team supervisor&#39;s guard fails closed on any Antigravity record shape it hasn&#39;t seen before. No team-member run and no real-model trial was done (<a href="https://github.com/albiexai/synth-city/issues/736" target="_blank" rel="noreferrer">#736</a>, <a href="https://github.com/albiexai/synth-city/pull/975" target="_blank" rel="noreferrer">PR #975</a>, <a href="https://github.com/albiexai/synth-city/issues/991" target="_blank" rel="noreferrer">#991</a>, <a href="https://github.com/albiexai/synth-city/pull/996" target="_blank" rel="noreferrer">PR #996</a>, <a href="https://github.com/albiexai/synth-city/issues/992" target="_blank" rel="noreferrer">#992</a>, <a href="https://github.com/albiexai/synth-city/pull/1001" target="_blank" rel="noreferrer">PR #1001</a>, <a href="https://github.com/albiexai/synth-city/issues/993" target="_blank" rel="noreferrer">#993</a>, <a href="https://github.com/albiexai/synth-city/pull/1004" target="_blank" rel="noreferrer">PR #1004</a>, <a href="https://github.com/albiexai/synth-city/issues/995" target="_blank" rel="noreferrer">#995</a>, <a href="https://github.com/albiexai/synth-city/pull/1005" target="_blank" rel="noreferrer">PR #1005</a>, <a href="https://github.com/albiexai/synth-city/issues/737" target="_blank" rel="noreferrer">#737</a>, <a href="https://github.com/albiexai/synth-city/pull/983" target="_blank" rel="noreferrer">PR #983</a>, <a href="https://github.com/albiexai/synth-city/issues/984" target="_blank" rel="noreferrer">#984</a>, <a href="https://github.com/albiexai/synth-city/pull/1020" target="_blank" rel="noreferrer">PR #1020</a>).</li><li><strong>Claude Code members can&#39;t edit while an unread stop or hold message waits.</strong> The managed <code>PreToolUse</code> hook now asks Synth City before <code>Edit</code>, <code>Write</code>, <code>MultiEdit</code>, <code>NotebookEdit</code> and Mail tools that change state. While the member has an unread stop, hold or decision message from its Leader, its bound Supervisor or Synth City, the call is refused with a reason that names only the message id. Reading the inbox lifts the refusal, and read-only tools are never refused. If Synth City can&#39;t be reached, the call is allowed and the hook prints a warning. Installing again upgrades an older hook. Other harnesses aren&#39;t guarded (<a href="https://github.com/albiexai/synth-city/issues/930" target="_blank" rel="noreferrer">#930</a>, <a href="https://github.com/albiexai/synth-city/pull/951" target="_blank" rel="noreferrer">PR #951</a>).</li><li><strong>Check a request before submitting it.</strong> The new owner-only tool <code>synth_city_preflight_request</code> checks a plan, scope-amendment or continuation request. It returns every mechanical problem at once, each with a code, a field and a message, and it writes nothing. A request that passes is not refused later for these rules, because submitting runs the same checks (<a href="https://github.com/albiexai/synth-city/issues/937" target="_blank" rel="noreferrer">#937</a>, <a href="https://github.com/albiexai/synth-city/pull/955" target="_blank" rel="noreferrer">PR #955</a>).</li><li><strong>A work item records its effort limit, notifies at the limit, and allows one Leader extension.</strong> An approved plan&#39;s estimate becomes the item&#39;s effort limit. The new per-scope setting <code>max_item_effort_minutes</code> (default 120) is the ceiling; an estimate above it is refused. When the advisory elapsed working time reaches the limit, the Leader and the owner each get one notice. The limit stops nothing. With the new tool <code>synth_city_extend_effort_limit</code>, the Leader can extend the limit once (<a href="https://github.com/albiexai/synth-city/issues/938" target="_blank" rel="noreferrer">#938</a>, <a href="https://github.com/albiexai/synth-city/pull/967" target="_blank" rel="noreferrer">PR #967</a>).</li><li><strong>The factory reports stuck work items and silent background failures.</strong> Four detectors open a finding while the condition lasts and close it when it clears: a merged item still verifying, a skipped item, a missing admission and a rolled-back poll. Each finding sends the Supervisor one notice. <code>/api/v1/health</code> reports <code>health</code>, <code>reasons</code> and <code>open_findings</code>, and <code>GET /api/v1/health/findings</code> lists the findings. The Overview shows a read-only &quot;Needs a look: operations&quot; card. See <a href="https://albiex.org/docs/autonomy" target="_blank" rel="noreferrer">Autonomous GitHub dispatch</a> (<a href="https://github.com/albiexai/synth-city/issues/941" target="_blank" rel="noreferrer">#941</a>, <a href="https://github.com/albiexai/synth-city/pull/956" target="_blank" rel="noreferrer">PR #956</a>).</li><li><strong>Automatic merge says why it did not run.</strong> An accepted, ready, unheld PR that isn&#39;t merged because the daily cap was reached, or because its item was escalated, gets a reason in the work-item note. The Leader and the bound Supervisor each get one notice. The repository settings page shows &quot;n of N in the last 24 hours&quot; next to the per-scope cap. An item escalated only because of a completed diagnostic revision goes back to the normal automatic-merge gates. See <a href="https://albiex.org/docs/autonomy" target="_blank" rel="noreferrer">Autonomous GitHub dispatch</a> (<a href="https://github.com/albiexai/synth-city/issues/939" target="_blank" rel="noreferrer">#939</a>, <a href="https://github.com/albiexai/synth-city/pull/953" target="_blank" rel="noreferrer">PR #953</a>).</li><li><strong>A generated review-summary comment from recorded facts (first part of #940).</strong> Synth City can render the Human review summary and the Work remaining block from recorded facts, and publish them as one PR comment that it owns. It never edits a PR or issue body. Publishing is off by default (<code>github_publish_summaries_enabled</code>). The Leader tools <code>synth_city_render_pull_summary</code> and <code>synth_city_publish_pull_summary</code> also work for PRs that Synth City doesn&#39;t track. Whether the GitHub App token can comment hasn&#39;t been checked live (<a href="https://github.com/albiexai/synth-city/issues/940" target="_blank" rel="noreferrer">#940</a>, <a href="https://github.com/albiexai/synth-city/pull/974" target="_blank" rel="noreferrer">PR #974</a>).</li><li><strong>Leader recovery.</strong> The Leader can cancel a revision, finalize a merged item or release a clean workspace with <code>synth_city_leader_cancel_revision</code>, <code>synth_city_leader_finalize_merged</code> and <code>synth_city_leader_release_workspace</code>. Each recovery records an audit fact and sends the Supervisor one notice, and stops if a HOLD arrives while it is checking. A release records that it has started before it does anything outside Synth City. If the credential revocation may have run, a corrected request needs a new operation id (<a href="https://github.com/albiexai/synth-city/issues/997" target="_blank" rel="noreferrer">#997</a>, <a href="https://github.com/albiexai/synth-city/pull/1009" target="_blank" rel="noreferrer">PR #1009</a>, <a href="https://github.com/albiexai/synth-city/issues/998" target="_blank" rel="noreferrer">#998</a>, <a href="https://github.com/albiexai/synth-city/pull/1019" target="_blank" rel="noreferrer">PR #1019</a>).</li><li><strong>An authenticated route to the review binding, for the reviewer only.</strong> <code>GET /github-work-items/{id}/review-binding</code> and the Mail tool <code>synth_city_get_review_binding</code> return the attempt binding a reviewer needs to record a head or revision review. Only the team&#39;s current verifier, or the reviewer named on the required-check watch for the PR&#39;s exact current head, may read it. Everyone else gets 403. The binding is private and must not be published (<a href="https://github.com/albiexai/synth-city/issues/999" target="_blank" rel="noreferrer">#999</a>, <a href="https://github.com/albiexai/synth-city/pull/1027" target="_blank" rel="noreferrer">PR #1027</a>).</li><li><strong>Isolated runtime kit: crash, relaunch and teardown.</strong> <code>crash --role cli</code> stops only the recorded CLI, and <code>relaunch</code> resumes the exact saved OpenCode session after a crash. <code>down</code> now also stops processes in a kit service&#39;s own process group; any other unrecorded process still makes it refuse. A recorded kit run with OpenCode 2.2.7 and a stub model showed that the question tool is not available to the member. Teardown of a real OpenCode member is not yet covered. See the <a href="https://albiex.org/docs/guide/isolated-runtime-kit" target="_blank" rel="noreferrer">isolated runtime kit guide</a> (<a href="https://github.com/albiexai/synth-city/issues/947" target="_blank" rel="noreferrer">#947</a>, <a href="https://github.com/albiexai/synth-city/pull/961" target="_blank" rel="noreferrer">PR #961</a>, <a href="https://github.com/albiexai/synth-city/issues/1010" target="_blank" rel="noreferrer">#1010</a>, <a href="https://github.com/albiexai/synth-city/pull/1012" target="_blank" rel="noreferrer">PR #1012</a>, <a href="https://github.com/albiexai/synth-city/issues/963" target="_blank" rel="noreferrer">#963</a>, <a href="https://github.com/albiexai/synth-city/pull/1017" target="_blank" rel="noreferrer">PR #1017</a>).</li><li><strong>A settings change now records how it was made (#945, first part).</strong> An audit event for a team settings change on <code>PATCH /api/v1/agent-teams/presets/{id}</code> stores <code>via</code>: <code>mail_tool</code> (a Mail session the server validated), <code>ui</code> or <code>api</code> (labels from the browser Origin header, not proof of the caller). A Mail session token that is unknown, closed or stale does not refuse the write; the event is recorded as unattributed with <code>session_invalid</code>. A campaign change on that route now records an event too, and the audit service can record an <code>external_actor</code> by actor id. The other operator routes follow in #1025 (<a href="https://github.com/albiexai/synth-city/issues/945" target="_blank" rel="noreferrer">#945</a>).</li><li><strong>The team view flags members whose Mail tool list is out of date (first part of #960).</strong> The Mail server reports a digest of the tools each session started with, and each member&#39;s status now carries <code>tool_catalog_state</code> (<code>current</code>, <code>stale</code> or <code>unknown</code>) judged over its connected sessions, with the reason &quot;tool catalog stale: restart in resume mode&quot; when stale. It is a display fact only and changes no wake, delivery or approval rule; restart a stale member in resume mode to load the new list. The roster badge and the <code>tools/list_changed</code> notification are separate follow-ups (<a href="https://github.com/albiexai/synth-city/issues/960" target="_blank" rel="noreferrer">#960</a>).</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>The backend CI suite runs as four parallel shards behind the required check.</strong> Each shard runs whole test files. The gate job keeps the required name <code>Full backend regression tests</code>, and fails unless every shard succeeded and every collected test ran exactly once. Two hosted runs took 10 min 14 s and 6 min 49 s, down from 21.6 to 28.5 minutes (<a href="https://github.com/albiexai/synth-city/issues/959" target="_blank" rel="noreferrer">#959</a>, <a href="https://github.com/albiexai/synth-city/pull/1011" target="_blank" rel="noreferrer">PR #1011</a>, <a href="https://github.com/albiexai/synth-city/issues/1013" target="_blank" rel="noreferrer">#1013</a>, <a href="https://github.com/albiexai/synth-city/pull/1028" target="_blank" rel="noreferrer">PR #1028</a>).</li><li><strong>The docs changelog page is generated from <code>CHANGELOG.md</code>.</strong> It now lists every released version, newest first, and a check fails if the page and <code>CHANGELOG.md</code> drift apart (<a href="https://github.com/albiexai/synth-city/issues/935" target="_blank" rel="noreferrer">#935</a>, <a href="https://github.com/albiexai/synth-city/pull/949" target="_blank" rel="noreferrer">PR #949</a>).</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>An item with a settled, accepted revision is promoted and merged automatically.</strong> A <code>verifying</code> item whose revision was settled positively, and whose open PR head the reviewer accepted with green required checks, now goes through the normal merge gates and merge policy. When it can&#39;t be promoted, the item shows &quot;Settled revision not promoted:&quot; followed by the reason (<a href="https://github.com/albiexai/synth-city/issues/957" target="_blank" rel="noreferrer">#957</a>, <a href="https://github.com/albiexai/synth-city/pull/962" target="_blank" rel="noreferrer">PR #962</a>).</li><li><strong>A merged or closed item gets its remaining-work context after its workspace is released.</strong> The Leader can again prepare the Remaining, Estimate and Next lines, built from the recorded verified head. The report context and the published marker carry a public <code>generation</code> reference instead of the dispatch nonce (<a href="https://github.com/albiexai/synth-city/issues/976" target="_blank" rel="noreferrer">#976</a>, <a href="https://github.com/albiexai/synth-city/pull/986" target="_blank" rel="noreferrer">PR #986</a>).</li><li><strong>Muse Code members are observed more reliably.</strong> A member that runs as another OS user is now observed from its own process&#39;s data folder. An unreadable log shows as <code>native_log_unreadable</code>, with its own roster text. A member busy on a long turn now shows as working when the turn began before the last 1 MiB of its log (the scan reaches back up to 8 MiB). A read-only probe and runbook let the operator check first-session discovery for a member that runs as another user; that discovery isn&#39;t yet verified in production. See <a href="https://albiex.org/docs/features/agent-teams" target="_blank" rel="noreferrer">Agent Teams</a> (<a href="https://github.com/albiexai/synth-city/issues/746" target="_blank" rel="noreferrer">#746</a>, <a href="https://github.com/albiexai/synth-city/pull/964" target="_blank" rel="noreferrer">PR #964</a>, <a href="https://github.com/albiexai/synth-city/issues/769" target="_blank" rel="noreferrer">#769</a>, <a href="https://github.com/albiexai/synth-city/pull/966" target="_blank" rel="noreferrer">PR #966</a>, <a href="https://github.com/albiexai/synth-city/issues/965" target="_blank" rel="noreferrer">#965</a>, <a href="https://github.com/albiexai/synth-city/pull/1014" target="_blank" rel="noreferrer">PR #1014</a>).</li><li><strong>Settling an accepted revision no longer fails with an HTTP 500 when GitHub reports a check run inconsistently.</strong> A run that GitHub gave as <code>in_progress</code> with a conclusion, or as <code>completed</code> with none, made the check observation refuse it (as intended, since reading it as green could pass a bad head), but the settlement route did not catch that and answered 500. It now answers 409 with <code>checks_not_observable:&lt;reason&gt;</code>, using only the observation&#39;s own fixed reason code, and leaves the attempt unchanged; the Leader settles again once the checks read consistently. Verification and the automatic-merge gate already kept such an item pending with a &quot;checks are unavailable&quot; note and charged no retry; tests now cover both shapes there too. The observation itself stays strict (<a href="https://github.com/albiexai/synth-city/issues/1007" target="_blank" rel="noreferrer">#1007</a>).</li><li><strong>A refused summary render now says why.</strong> <code>synth_city_render_github_summary</code> returned the same <code>invalid_github_summary</code> code for a mistyped expected body hash, an oversized body, bad or misplaced summary markers, a foreign section inside the block and bad summary text, so a body that rendered on a test call looked as if its content was refused. The code stays, and the answer now also carries a <code>reason</code> (<code>body_changed</code>, <code>body_invalid</code>, <code>rendered_body_too_large</code>, <code>summary_markers_ambiguous</code>, <code>summary_markers_invalid</code>, <code>summary_contains_foreign_section</code> or <code>invalid_summary_field</code>) with the names of the failing fields, never their values, and a matching suggestion. No guard was relaxed (<a href="https://github.com/albiexai/synth-city/issues/987" target="_blank" rel="noreferrer">#987</a>).</li><li><strong>The factory status read counts shared Muse Code and Antigravity sessions like the team read does.</strong> The factory snapshot looked for slots sharing a native session id among Codex and Claude Code slots only, while the team read also included Muse Code and Antigravity. For Antigravity the shared conversation was therefore not flagged in the factory view, where the team read reports it as unattributable; for Muse Code only the snapshot&#39;s inputs differed, because the Muse observer does not use the flag today. All three places now read one provider list (<a href="https://github.com/albiexai/synth-city/issues/982" target="_blank" rel="noreferrer">#982</a>).</li><li><strong>The recorded estimate and effort limit are visible, and the Leader&#39;s extension stays under the scope ceiling.</strong> The revision list, the work-item context (<code>synth_city_get_work_item_context</code>) and the request preflight now show the item&#39;s recorded estimate, approved limit, any extension, the scope ceiling and the room left for an extension. The extension is clamped so that the limit plus the extension never passes <code>max_item_effort_minutes</code> (<a href="https://github.com/albiexai/synth-city/issues/968" target="_blank" rel="noreferrer">#968</a>).</li><li><strong>Auto-merge now runs when the last revision was superseded.</strong> An item whose submitted revision a Leader had ended after a negative review stayed &quot;dispatched&quot; even after the reviewer accepted a later head, so the PR needed a hand merge. It is now verified at the accepted head and goes through the same gates as any other PR: the exact-head acceptance, green required checks, the hold label, the Leader approval and the merge policy. A reason is recorded when a gate stops it (<a href="https://github.com/albiexai/synth-city/issues/972" target="_blank" rel="noreferrer">#972</a>).</li><li><strong>Harnesses pages show the agents&#39; global scope and let you choose it.</strong> On an install where the controller and the agents run as different users, Claude Code&#39;s global scope no longer reads the controller&#39;s own <code>~/.claude</code>. Set <code>harness_agent_user</code> to show the agent user&#39;s skills, agents, commands, hooks, MCP servers and memory. A <strong>Global scope of</strong> control switches users, and each page names the folder it reads and says when the controller cannot write there (<a href="https://github.com/albiexai/synth-city/issues/969" target="_blank" rel="noreferrer">#969</a>).</li></ul><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li><strong>Unauthenticated team reads no longer return the dispatch nonce.</strong> The work-item progress read and the preset work-item list now return <code>dispatch_nonce</code> as <code>null</code>. They identify the dispatch by <code>dispatch_generation</code>, a one-way public reference that no route accepts as authority. Routes that require authentication keep the nonce that operator actions need. The dispatch branch name and the publication URL still contain the nonce; that follow-up is planned for 4.3 (<a href="https://github.com/albiexai/synth-city/issues/1000" target="_blank" rel="noreferrer">#1000</a>) (<a href="https://github.com/albiexai/synth-city/issues/988" target="_blank" rel="noreferrer">#988</a>, <a href="https://github.com/albiexai/synth-city/pull/1002" target="_blank" rel="noreferrer">PR #1002</a>).</li></ul><h2 id="_4-1-0-2026-11-14" tabindex="-1">[4.1.0] - 2026-11-14 <a class="header-anchor" href="#_4-1-0-2026-11-14" aria-label="Permalink to &quot;[4.1.0] - 2026-11-14&quot;">​</a></h2><p>Albiex Synth City 4.1.0 makes the delivery factory steadier: owners can amend an approved plan, automatic merges require the reviewer&#39;s acceptance of the exact head, dispatch follows priority labels, and several stuck states now settle on their own.</p><p><strong>Not in this release (planned for 4.2):</strong> live runtime acceptance for OpenCode 2 members, the Antigravity CLI harness, the Muse Code observation fixes, automatic dispatch-workspace provisioning, external actor token revocation, the backend CI speed-up and live Mail tool-list refresh.</p><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>OpenCode 2 members.</strong> Albiex Synth City accepts OpenCode 2 or later only and refuses OpenCode 1 (<a href="https://github.com/albiexai/synth-city/issues/730" target="_blank" rel="noreferrer">#730</a>, <a href="https://github.com/albiexai/synth-city/pull/876" target="_blank" rel="noreferrer">PR #876</a>). The OpenCode launch contract is reworked for OpenCode 2 (<a href="https://github.com/albiexai/synth-city/issues/731" target="_blank" rel="noreferrer">#731</a>, <a href="https://github.com/albiexai/synth-city/pull/879" target="_blank" rel="noreferrer">PR #879</a>). The Install tab and the Harnesses page set up Agent Mail for OpenCode 2, and the install denies OpenCode&#39;s question tool (<a href="https://github.com/albiexai/synth-city/issues/732" target="_blank" rel="noreferrer">#732</a>, <a href="https://github.com/albiexai/synth-city/pull/884" target="_blank" rel="noreferrer">PR #884</a>). See <a href="https://albiex.org/docs/features/harnesses" target="_blank" rel="noreferrer">Harnesses</a>.</li><li><strong>Claude Code model and reasoning effort per team member</strong>, on every platform and not only on Amazon Bedrock (<a href="https://github.com/albiexai/synth-city/issues/869" target="_blank" rel="noreferrer">#869</a>, <a href="https://github.com/albiexai/synth-city/pull/889" target="_blank" rel="noreferrer">PR #889</a>). See <a href="https://albiex.org/docs/features/agent-teams" target="_blank" rel="noreferrer">Agent Teams</a>.</li><li><strong>Dispatch priority labels</strong> <code>priority:1</code> to <code>priority:9999</code> order ready issues, with the oldest issue first as the fallback (<a href="https://github.com/albiexai/synth-city/issues/795" target="_blank" rel="noreferrer">#795</a>, <a href="https://github.com/albiexai/synth-city/pull/888" target="_blank" rel="noreferrer">PR #888</a>).</li><li><strong>Required-check watch.</strong> The assigned reviewer and the Leader are woken when a PR&#39;s required checks finish, and a team that has stopped moving is flagged (<a href="https://github.com/albiexai/synth-city/issues/839" target="_blank" rel="noreferrer">#839</a>, <a href="https://github.com/albiexai/synth-city/pull/878" target="_blank" rel="noreferrer">PR #878</a>).</li><li><strong>Healthy scope amendments and submitted-revision settlement.</strong> An owner can amend an approved plan, and a submitted revision can be ended cleanly after review requires changes (<a href="https://github.com/albiexai/synth-city/issues/859" target="_blank" rel="noreferrer">#859</a>, <a href="https://github.com/albiexai/synth-city/pull/882" target="_blank" rel="noreferrer">PR #882</a>). Approved plans carry companion paths: the tests, fixtures, docs and generated contracts that travel with the files they name (<a href="https://github.com/albiexai/synth-city/issues/901" target="_blank" rel="noreferrer">#901</a>, <a href="https://github.com/albiexai/synth-city/pull/907" target="_blank" rel="noreferrer">PR #907</a>).</li><li><strong>Auto-merge only after reviewer acceptance.</strong> With the automatic merge policy a code PR merges only when the team&#39;s reviewer accepted its exact current head (<a href="https://github.com/albiexai/synth-city/issues/904" target="_blank" rel="noreferrer">#904</a>, <a href="https://github.com/albiexai/synth-city/pull/915" target="_blank" rel="noreferrer">PR #915</a>). The review hold label still blocks automatic merge. See <a href="https://albiex.org/docs/autonomy" target="_blank" rel="noreferrer">Autonomous GitHub dispatch</a>.</li><li><strong>Isolated runtime kit</strong> for provider live checks (<a href="https://github.com/albiexai/synth-city/issues/902" target="_blank" rel="noreferrer">#902</a>, <a href="https://github.com/albiexai/synth-city/pull/905" target="_blank" rel="noreferrer">PR #905</a>). See the <a href="https://albiex.org/docs/guide/isolated-runtime-kit" target="_blank" rel="noreferrer">isolated runtime kit guide</a>.</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Leader plan-approval wait.</strong> A busy Leader&#39;s pending plan approval stays active for a bounded, activity-aware wait instead of escalating at once (<a href="https://github.com/albiexai/synth-city/issues/843" target="_blank" rel="noreferrer">#843</a>, <a href="https://github.com/albiexai/synth-city/pull/874" target="_blank" rel="noreferrer">PR #874</a>).</li><li><strong>Scope amendment rules.</strong> Only approved amendments count toward the limit of three (<a href="https://github.com/albiexai/synth-city/issues/906" target="_blank" rel="noreferrer">#906</a>, <a href="https://github.com/albiexai/synth-city/pull/911" target="_blank" rel="noreferrer">PR #911</a>). The approved plan&#39;s file list is read from <code>allowed_paths</code> or <code>paths</code> (<a href="https://github.com/albiexai/synth-city/issues/908" target="_blank" rel="noreferrer">#908</a>, <a href="https://github.com/albiexai/synth-city/pull/910" target="_blank" rel="noreferrer">PR #910</a>). A healthy scope amendment is no longer refused for items with acknowledged plans or <code>origin/</code> base refs (<a href="https://github.com/albiexai/synth-city/issues/890" target="_blank" rel="noreferrer">#890</a>, <a href="https://github.com/albiexai/synth-city/pull/892" target="_blank" rel="noreferrer">PR #892</a>). An active continuation on an escalated item can be settled or amended (<a href="https://github.com/albiexai/synth-city/issues/887" target="_blank" rel="noreferrer">#887</a>, <a href="https://github.com/albiexai/synth-city/pull/897" target="_blank" rel="noreferrer">PR #897</a>).</li></ul><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Cross-user terminal lanes.</strong> When agents run as another user and the attach fails, the lane shows one fixed message, and the message names the <code>!use_pty</code> rule when <code>sudo</code> cannot allocate its own pty (<a href="https://github.com/albiexai/synth-city/issues/749" target="_blank" rel="noreferrer">#749</a>, <a href="https://github.com/albiexai/synth-city/pull/877" target="_blank" rel="noreferrer">PR #877</a>).</li></ul><h3 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h3><ul><li>If the controller and the agents run as different operating-system users, the operator adds a command-scoped <code>!use_pty</code> rule to <code>sudoers</code> for the agent <code>tmux</code> command. Albiex Synth City does not change <code>sudoers</code>. See <a href="https://albiex.org/docs/features/agent-bridge" target="_blank" rel="noreferrer">Live sessions</a> and <a href="https://albiex.org/docs/guide/installation" target="_blank" rel="noreferrer">Installation</a>.</li></ul><h3 id="evidence-limits" tabindex="-1">Evidence limits <a class="header-anchor" href="#evidence-limits" aria-label="Permalink to &quot;Evidence limits&quot;">​</a></h3><ul><li>Several of these changes were checked with unit, component, mocked-render and hosted CI evidence. This entry makes no claim about a live check with a real OpenCode member or about OpenCode working and idle states; the Harnesses page lists those as not yet available.</li></ul><h2 id="_4-0-0" tabindex="-1">[4.0.0] <a class="header-anchor" href="#_4-0-0" aria-label="Permalink to &quot;[4.0.0]&quot;">​</a></h2><h3 id="albiex-synth-city-v4-0-0-—-formerly-claude-deck" tabindex="-1">Albiex Synth City v4.0.0 — formerly Claude Deck <a class="header-anchor" href="#albiex-synth-city-v4-0-0-—-formerly-claude-deck" aria-label="Permalink to &quot;Albiex Synth City v4.0.0 — formerly Claude Deck&quot;">​</a></h3><p><strong>Albiex Synth City</strong> is the new name of Claude Deck. Same project, same data, new name — now developed as <code>albiexai/synth-city</code> and documented at <code>albiex.org</code>. Old links redirect.</p><p><strong>Upgrading from v3.1:</strong> stop the old version completely first, back up while stopped, then get v4.0.0 the normal source-based way (update source + dependencies, see the installation guide) and start it. Your database (<code>claude_registry.db</code> → <code>synth_city.db</code>), backups and attachments (<code>~/.claude-registry</code> → <code>~/.albiex-synth-city</code>), teams, settings and Agent Mail history move automatically on first start — no migration command, no manual renaming for a standard install. Read the <a href="https://github.com/albiexai/synth-city/blob/v4.0.0/docs/guide/migration-v4.md" target="_blank" rel="noreferrer">migration guide</a> before upgrading if you customised paths, environment variables, agent connections, or scripts.</p><p><strong>Breaking changes (complete list):</strong></p><ul><li>Old runtime names stop working; there are no aliases and no grace period.</li><li><code>CLAUDE_DECK_*</code> → <code>SYNTH_CITY_*</code> environment variables. Hand-set instance/supervisor variables must be renamed; startup warns (names only, never values) if old ones remain set.</li><li>Agent Mail tools <code>deck_*</code> → <code>synth_city_*</code>; MCP server <code>claude-deck-mail</code> → <code>albiex-synth-city-mail</code>. Mail-setup connections the app can positively recognise are rewritten automatically (temporary failures retry on later starts; persistent failures are reported as incomplete, never as done); unrecognised or hand-written ones are left untouched, reported as needing attention, and must be re-added.</li><li>API headers <code>X-Deck-*</code> / <code>X-Claude-Deck-Terminal-Token</code> → <code>X-Synth-City-*</code>; error codes <code>deck_unreachable</code> / <code>deck_http_error</code> → <code>synth_city_unreachable</code> / <code>synth_city_http_error</code>. Sessions must be relaunched and get fresh session credentials; the operator token is unchanged (re-enter it in the browser if the tab was closed) and authorisation checks are unchanged.</li><li>Default database and data-folder paths renamed (above). Genuinely custom locations stay put; explicitly configured shipped defaults migrate automatically; overlapping custom locations may cause a safe stop instead of a move (see the migration guide).</li><li>New queues/scopes default to labels <code>albiex-synth-city-ready</code> / <code>albiex-synth-city-design</code>; existing scopes keep working with their current labels.</li><li>Release-download file names changed: <code>claude-deck-frontend-v…</code> → <code>albiex-synth-city-frontend-v…</code>; scripts that download releases must use the new names.</li><li>Downgrade is restore-the-complete-pre-upgrade-set only (database set, data folder, provider configuration and browser state) — see the migration guide.</li></ul><p><strong>Not changed:</strong> your data model and history, backup file contents, the operator token configured on the server, and the internal identifiers that existing databases depend on. (Agent <em>session</em> credentials are the deliberate exception above: relaunched sessions register fresh ones.)</p><p>Full rename design and upgrade contract: <a href="https://github.com/albiexai/synth-city/blob/v4.0.0/docs/plans/2026-11-06-rename-synth-city/compatibility.md" target="_blank" rel="noreferrer">compatibility design</a>. Report upgrade problems with your startup log — never post tokens or credentials.</p><h2 id="_3-1-0-2026-10-14" tabindex="-1">[3.1.0] - 2026-10-14 <a class="header-anchor" href="#_3-1-0-2026-10-14" aria-label="Permalink to &quot;[3.1.0] - 2026-10-14&quot;">​</a></h2><p>v3.1 makes the factory pages readable for a Director, and hardens the local API.</p><h3 id="upgrade-notes" tabindex="-1">Upgrade notes <a class="header-anchor" href="#upgrade-notes" aria-label="Permalink to &quot;Upgrade notes&quot;">​</a></h3><ul><li><strong>Node.js 22.12 or later</strong> is now required to build and test the frontend. Vite 8 and Vitest 5 need it. <code>scripts/install.sh</code> checks the version.</li><li><strong>Agent Mail authentication is strict by default.</strong> Agents need their Mail session credential, and external actors read and write only threads they created or are addressed in. When a Director key is configured, Agent Mail setup, member edits, actor creation and the UI&#39;s Mail reads need it. An install with no Director key keeps working as before and shows a recommendation to set one. An explicit opt-out restores the earlier unauthenticated reads; writes always need a key. See the Agent Mail guide.</li><li><strong>Controller upgrades:</strong> the maintenance upgrade now tolerates nullable columns that a startup migration adds, and accepts checkpoints from owners that work in a leased dispatch workspace. Its CLI prints the refusal reason code.</li></ul><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Overview:</strong> answers what has happened, what is happening and what still needs to happen. It shows a campaign progress bar, a team summary card, the supervisor&#39;s status, unanswered release reminders, and items that wait for someone.</li><li><strong>Teams:</strong> a readable team page (header and members first, editing behind Edit team), a link from a team to its parent issue, and From Bridge and From Mail creation from the selected sessions only.</li><li><strong>Audit:</strong> a plain-language delivery summary, a readable activity feed, a &quot;Needs a look&quot; panel for refused agent requests, and Team, Repository and Window selects. Events unlock only when the Director chooses to.</li><li><strong>Agent Mail:</strong> &quot;Waiting on someone&quot; first, conversations grouped by team, a compact roster, the sender shown as Deck, Director or agent, and Mail setup on each harness page.</li><li><strong>Live sessions:</strong> a readable session list with Kill away from Watch, Team lanes that show every member four at a time, and the shared Director-key prompt for new sessions.</li><li><strong>Harnesses:</strong> breadcrumbs, a page per harness with grouped native pages, a compact list, and local projects folded into harness pages.</li><li><strong>Factory signals:</strong> one shared agent status across Agent Mail, Live sessions and Teams; an attention signal when required CI cannot be read; an optional supervisor check-in; unattended-launch results.</li><li><strong>E2E journeys:</strong> an isolated Playwright instance with deterministic seed data, and a required <code>e2e</code> CI job. Every lane has active journeys, including contrast, keyboard and a no-flicker check of the factory pages.</li></ul><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Work and Repositories</strong> are the single home of a work item and of repository setup. The Work list is compact and defaults to active work. Repository setup no longer asks for the key on entry or requires hand-typed paths.</li><li><strong>Plain-language copy</strong> on Director-facing pages: for example &quot;Teams&quot;, &quot;Director&quot; and &quot;updated&quot; times.</li><li><strong>Frontend dependencies:</strong> Tailwind CSS 4, Vite 8 with plugin-react 6, lucide-react 1.x and Vitest 5.</li></ul><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Flicker:</strong> the factory pages no longer show a &quot;Refreshing…&quot; line or flash &quot;Previous&quot; labels during each background refresh.</li><li><strong>Delivery:</strong> a pending check no longer uses up the merge retry budget; draft PRs are never promoted or auto-merged, and a configured review-hold label is honoured; a status report cannot move a merged item back to escalated.</li><li><strong>Dispatch:</strong> the Leader acknowledgement deadline starts when the plan request arrives; native owner contact renews in a leased dispatch workspace; workspace-release reminders are bounded; a merged item keeps no active continuation revision.</li><li><strong>Factory pages</strong> stop polling after a permanent 404 or 422, show local times in the right time zone, show a way back and plain errors on the Work item page, and keep the reader&#39;s place on Audit.</li><li><strong>Accessibility:</strong> WCAG AA contrast fixes in both themes (team cards, Autonomy, Agent Mail badges, Live sessions counts, Team lanes labels).</li></ul><h3 id="security-1" tabindex="-1">Security <a class="header-anchor" href="#security-1" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li><strong>Local API hardening:</strong> settings writes need the Director key when one is configured; Agent Mail authentication defaults as described in the upgrade notes; the Agent Mail install routes need the Director key.</li><li><strong>Unattended team sessions:</strong> interactive question prompts are blocked, and workspaces are pre-trusted for team sessions.</li></ul><h2 id="_3-0-0-2026-10-09" tabindex="-1">[3.0.0] - 2026-10-09 <a class="header-anchor" href="#_3-0-0-2026-10-09" aria-label="Permalink to &quot;[3.0.0] - 2026-10-09&quot;">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Overview, Work and Repositories</strong>: Show factory work counts, owners, waiting reasons, pull request context, and watched-scope intake, polling and overlap observations across teams.</li><li><strong>Harnesses</strong>: Show the versioned operations and readiness catalog for Claude Code, Codex CLI, GitHub Copilot CLI, OpenCode CLI and Pi, with guarded native pages. The catalog does not create an editor or grant authority.</li><li><strong>Guided repository configuration</strong>: <code>/repositories/new</code> keeps the draft, the saved configuration, the reviewed launch and the activation as separate steps.</li><li><strong>Explicit Leader authority</strong>: Teams sets the Leader through the team&#39;s <code>leader_slot_id</code>.</li><li><strong>Audit history and metrics</strong>: The factory audit ledger and delivery metrics record observed actions and outcomes. See <code>docs/guide/factory-audit-and-metrics.md</code>.</li><li><strong>Agent Bridge</strong>: Codex CLI sessions can launch on Amazon Bedrock with a provider-aware platform selector, a per-session <code>model_provider = &quot;amazon-bedrock&quot;</code> override, and optional AWS region, profile and model fields.</li><li><strong>Version sync</strong>: <code>scripts/bump-version.sh</code> also syncs <code>frontend/package-lock.json</code>, <code>backend/uv.lock</code> and the backend <code>app_version</code>.</li></ul><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Product positioning</strong>: Claude Deck is a self-hosted workspace to observe and intervene in bounded coding-agent attempts on GitHub issues, with mixed harnesses, visible policies and recovery controls. Native configuration and manual sessions stay available without automatic dispatch.</li><li><strong>Version</strong>: The runtime version response and the application package metadata report 3.0.0.</li><li><strong>CI</strong>: Product CI also runs for pull requests and pushes on <code>release/v3.0.0</code>.</li><li><strong>Upgrade</strong>: Existing databases upgrade in place. Back up <code>backend/claude_registry.db</code> first. Downgrade restores that backup. See <code>docs/guide/installation.md</code>.</li></ul><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Agent Teams</strong>: Unsafe multi-slot Codex <code>resume --last</code> launches in the same repository are blocked. Codex hook session keys stay distinct per team slot.</li><li><strong>Agent Mail</strong>: Compose labels offline and not-wakeable recipients clearly before storing mail for later delivery.</li></ul><h3 id="evidence-limits-1" tabindex="-1">Evidence limits <a class="header-anchor" href="#evidence-limits-1" aria-label="Permalink to &quot;Evidence limits&quot;">​</a></h3><ul><li>Finished is a tracking state. It is not independently reviewed delivery, reliability, cost or time saved.</li><li>Cost is unknown. This release makes no performance, cost or time-saving claim.</li><li>Native adapters stay provider-specific. Catalog support does not mean equal native capability across harnesses.</li><li>The manual Bridge trial (V14) is not performed. Pilot participants, comparisons and human benefit measurements are not available.</li></ul><h2 id="_2-0-1-2026-06-20" tabindex="-1"><a href="https://github.com/adrirubio/claude-deck/compare/v2.0.0...v2.0.1" target="_blank" rel="noreferrer">2.0.1</a> - 2026-06-20 <a class="header-anchor" href="#_2-0-1-2026-06-20" aria-label="Permalink to &quot;[2.0.1] - 2026-06-20&quot;">​</a></h2><h3 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Claude Code Config</strong>: Added coverage for current Claude Code settings such as advisor model, fallback model chains, Remote Control startup, push notifications, notification channel, theme, auto-compact, file checkpointing, and newer safety/privacy toggles.</li><li><strong>Config editor helpers</strong>: Added validated JSON editing for complex settings objects/arrays and a boolean map editor for plugin enablement.</li></ul><h3 id="changed-4" tabindex="-1">Changed <a class="header-anchor" href="#changed-4" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Dashboard</strong>: Dashboard cards and navigation are now provider-aware so Codex selection does not show inaccessible Claude Code-only cards as if they were Codex pages.</li><li><strong>Codex provider pages</strong>: Codex MCP servers, plugins, feature flags, and configuration inventory now route to provider-appropriate pages instead of dead-end dashboard stats.</li><li><strong>Claude Code settings</strong>: Plugin marketplace settings, worktree symlink directories, sandbox Mach lookup settings, and managed marketplace policy values now use the JSON shapes documented by Claude Code.</li><li><strong>Docs</strong>: Refreshed release, Config, and Dashboard docs to describe the 2.0.1 stabilization fixes.</li></ul><h3 id="fixed-4" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-4" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Usage costs</strong>: Claude Code usage dashboards now calculate costs for current Claude model aliases such as Sonnet 5, Fable 5, Opus 4.6/4.7/4.8, Sonnet 4.6, and Haiku 4.5 instead of showing <code>$0.00</code> with non-zero token usage.</li><li><strong>Usage cache</strong>: Usage cache keys now include the pricing table version, avoiding stale zero-cost aggregates after pricing support changes.</li><li><strong>Config defaults</strong>: Corrected stale UI defaults/descriptions for auto-updates, sandbox auto-allow, thinking summaries, plan auto-mode, and turn duration.</li></ul><h2 id="_2-0-0-2026-06-19" tabindex="-1"><a href="https://github.com/adrirubio/claude-deck/compare/v1.3.1...v2.0.0" target="_blank" rel="noreferrer">2.0.0</a> - 2026-06-19 <a class="header-anchor" href="#_2-0-0-2026-06-19" aria-label="Permalink to &quot;[2.0.0] - 2026-06-19&quot;">​</a></h2><h3 id="added-5" tabindex="-1">Added <a class="header-anchor" href="#added-5" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Agent Mail</strong>: Durable local mailbox coordination for Claude Code and Codex CLI agents <ul><li>Per-repository and Agent Team slot participants with role and charter metadata</li><li>Structured direct messages, context requests, handoffs, replies, read state, acknowledgements, and inbox load</li><li>Agent-facing MCP tools for team discovery, inbox checks, replies, context requests, and handoffs</li><li>One-click install and uninstall flows for Claude Code and Codex MCP/hooks configuration with best-effort backups</li><li>Best-effort tmux wake nudges for visible sessions through Agent Bridge</li></ul></li><li><strong>Agent Teams</strong>: Saved rosters for launching or reusing local agent sessions <ul><li>Manual team creation, team creation from Agent Mail participants, and team creation from visible Agent Bridge sessions</li><li>Team slots with provider, repository, display name, role, charter, bootstrap prompt, launch mode, provider options, and enabled state</li><li>Launch planning that checks provider availability, Agent Mail readiness, reusable tmux sessions, disabled slots, and launch option validity</li><li>Same-repository planner/reviewer and implementer workflows through distinct Agent Mail team-slot identities</li></ul></li><li><strong>External local orchestration</strong>: Token-bound same-machine Agent Mail API for tools such as OpenClaw <ul><li>External actor registration, member discovery, direct messages, broadcasts, context requests, handoffs, replies, request status, bounded waits, and acknowledgements</li><li>Agent Teams launch endpoints usable by local external automation after plan review</li></ul></li><li><strong>Agent Bridge session creation</strong>: Searchable project picker and Codex model/profile selectors with custom-value fallback.</li></ul><h3 id="changed-5" tabindex="-1">Changed <a class="header-anchor" href="#changed-5" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Multi-agent workflow</strong>: Agent Bridge, Agent Mail, and Agent Teams are now the supported surfaces for local session visibility, communication, and reusable rosters.</li><li><strong>Agent Mail dashboard</strong>: Connected, observed-only, not wakeable, and inbox-load states now describe delivery behavior more explicitly.</li><li><strong>Agent Mail docs</strong>: Setup documentation now explains required MCP/hooks configuration and the current tmux-only wake path.</li><li><strong>Dependencies</strong>: Merged low-risk package updates including React package alignment and small UI/runtime dependency updates.</li></ul><h3 id="removed" tabindex="-1">Removed <a class="header-anchor" href="#removed" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li><strong>Presence</strong>: Removed the Presence frontend route, backend route/service, hook integration, tests, and navigation. Existing inert SQLite tables may remain in local databases, but no active backend polling or UI surface uses them.</li></ul><h3 id="fixed-5" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-5" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Agent Mail install feedback</strong>: Install and uninstall actions now refresh status and show clearer results for Claude Code and Codex configuration.</li><li><strong>Agent Mail roster accuracy</strong>: Dashboard member counts now distinguish durable members from observed sessions and collapse bridge-observed/MCP sessions under the same member where appropriate.</li><li><strong>Agent Mail hook output</strong>: Claude Code and Codex hooks return provider-valid JSON so hook failures are not shown for normal mailbox checks.</li><li><strong>Agent Bridge startup flow</strong>: The development script now avoids transient frontend proxy noise by coordinating backend/frontend startup more carefully.</li></ul><h3 id="security-2" tabindex="-1">Security <a class="header-anchor" href="#security-2" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li><strong>External Agent Mail boundary</strong>: External actor creation is loopback-only, external endpoints require bearer tokens, and per-actor rate limits protect the local orchestration surface within Claude Deck&#39;s existing local trust model.</li></ul><h2 id="_1-3-1-2026-06-11" tabindex="-1"><a href="https://github.com/adrirubio/claude-deck/compare/v1.3.0...v1.3.1" target="_blank" rel="noreferrer">1.3.1</a> - 2026-06-11 <a class="header-anchor" href="#_1-3-1-2026-06-11" aria-label="Permalink to &quot;[1.3.1] - 2026-06-11&quot;">​</a></h2><h3 id="fixed-6" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-6" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Frontend runtime alignment</strong>: Aligned <code>react</code> and <code>react-is</code> with the installed React DOM version to avoid production render failures from mixed React package versions.</li></ul><h3 id="changed-6" tabindex="-1">Changed <a class="header-anchor" href="#changed-6" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Documentation screenshots</strong>: Refreshed README screenshots, including the Agent Bridge mixed-provider view, dashboard, config, and MCP visuals used for the release.</li></ul><h2 id="_1-3-0-2026-06-08" tabindex="-1"><a href="https://github.com/adrirubio/claude-deck/compare/v1.2.0...v1.3.0" target="_blank" rel="noreferrer">1.3.0</a> - 2026-06-08 <a class="header-anchor" href="#_1-3-0-2026-06-08" aria-label="Permalink to &quot;[1.3.0] - 2026-06-08&quot;">​</a></h2><h3 id="added-6" tabindex="-1">Added <a class="header-anchor" href="#added-6" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Codex CLI support</strong>: Provider-aware Codex support is now stable enough for everyday use <ul><li>Agent Bridge discovers mixed Claude Code and Codex tmux sessions</li><li>Codex sessions can be spawned, resumed, forked, attached to, and killed from the UI</li><li>Provider switcher keeps Claude Code and Codex surfaces separate instead of showing unsupported pages</li></ul></li><li><strong>Codex Config</strong>: Safe TOML editor for Codex settings <ul><li>Structured General and Runtime cards for model, profile, reasoning effort, sandbox mode, approval policy, search, strict config, and alternate screen behavior</li><li>Dropdowns for known Codex enum values while keeping open-ended fields editable</li><li>Help tooltips for documented settings and feature flags</li><li>Feature flag inventory from <code>codex features list</code>, including editable overrides for flags such as goals, memories, hooks, multi-agent, shell tool, and network proxy</li><li>Profile diagnostics for active/default profile resolution, profile files, overrides, missing references, and malformed profiles</li></ul></li><li><strong>Codex MCP and Plugins</strong>: Provider inventory and safe CLI-backed mutations <ul><li>MCP inventory from <code>codex mcp list --json</code></li><li>MCP add/remove through the Codex CLI with validation</li><li>Plugin inventory from <code>codex plugin list</code></li><li>Plugin install/remove where the installed Codex CLI exposes safe commands</li></ul></li><li><strong>Codex Backup Export</strong>: Redacted export-only backups for Codex config, profile files, rules, and provider inventory metadata</li><li><strong>Projects</strong>: Project discovery is easier, with directory browsing support when adding project paths</li></ul><h3 id="changed-7" tabindex="-1">Changed <a class="header-anchor" href="#changed-7" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Provider model</strong>: Provider status, capabilities, diagnostics, and normalized errors now drive the UI for Claude Code and Codex CLI.</li><li><strong>Documentation</strong>: README and VitePress docs now describe the stable Codex support surface, the remaining provider boundaries, and the release-ready dependency updates.</li><li><strong>Frontend toolchain</strong>: Updated TypeScript to 6.0.3, <code>@vitejs/plugin-react</code> to 5.1.4, ESLint tooling, React DOM, PostCSS, Tailwind Merge, and Node types.</li></ul><h3 id="security-3" tabindex="-1">Security <a class="header-anchor" href="#security-3" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li><strong>Codex privacy boundary</strong>: Codex auth, history, model cache, SQLite state, prompt text, and raw cache payloads remain excluded from raw viewers and backups.</li><li><strong>Codex restore policy</strong>: Automatic Codex restore is refused because exports intentionally omit provider-owned local state.</li></ul><h2 id="_1-2-0-2026-04-22" tabindex="-1"><a href="https://github.com/adrirubio/claude-deck/compare/v1.1.0...v1.2.0" target="_blank" rel="noreferrer">1.2.0</a> - 2026-04-22 <a class="header-anchor" href="#_1-2-0-2026-04-22" aria-label="Permalink to &quot;[1.2.0] - 2026-04-22&quot;">​</a></h2><h3 id="added-7" tabindex="-1">Added <a class="header-anchor" href="#added-7" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>CC Bridge</strong>: Live terminal bridge to Claude Code sessions running in tmux <ul><li>Multi-terminal grid layout supporting up to 4 simultaneous panes (auto-layout: 1, 2-column, or 2x2 grid)</li><li>Per-pane read-only/interactive mode toggle, fullscreen, attach/detach, and close controls</li><li>Active terminal focus indicator — green glow on the focused pane</li><li>Session discovery via <code>tmux list-panes</code> with auto-refresh polling</li><li>Spawn new Claude Code sessions (plain, worktree, or resume mode) from the UI</li><li>Kill sessions with optional worktree cleanup</li><li>WebSocket-based PTY relay with xterm.js (WebGL rendering, web links)</li></ul></li><li><strong>Projects</strong>: Discover projects from <code>~/.claude/projects/</code> session history</li><li><strong>Dashboard</strong>: Cache stats in context to avoid re-fetching on navigation</li><li><strong>Documentation</strong>: VitePress documentation site with guide, features, and API reference</li></ul><h3 id="fixed-7" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-7" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>CC Bridge</strong>: Prevent orphaned <code>tmux attach-session</code> processes from accumulating on server reload/crash via <code>PR_SET_PDEATHSIG</code> and startup cleanup</li><li><strong>CC Bridge</strong>: Fix terminal not rendering in React StrictMode due to race condition in async attach flow</li></ul><h2 id="_1-1-0-2026-03-03" tabindex="-1"><a href="https://github.com/adrirubio/claude-deck/compare/v1.0.0...v1.1.0" target="_blank" rel="noreferrer">1.1.0</a> - 2026-03-03 <a class="header-anchor" href="#_1-1-0-2026-03-03" aria-label="Permalink to &quot;[1.1.0] - 2026-03-03&quot;">​</a></h2><h3 id="added-8" tabindex="-1">Added <a class="header-anchor" href="#added-8" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>CC Bridge</strong>: Live terminal bridge to Claude Code sessions running in tmux <ul><li>Multi-terminal grid layout supporting up to 4 simultaneous panes (auto-layout: 1, 2-column, or 2x2 grid)</li><li>Per-pane read-only/interactive mode toggle, fullscreen, attach/detach, and close controls</li><li>Active terminal focus indicator — green glow on the focused pane</li><li>Session discovery via <code>tmux list-panes</code> with auto-refresh polling</li><li>Spawn new Claude Code sessions (plain, worktree, or resume mode) from the UI</li><li>Kill sessions with optional worktree cleanup</li><li>WebSocket-based PTY relay with xterm.js (WebGL rendering, web links)</li></ul></li><li><strong>Projects</strong>: Discover projects from <code>~/.claude/projects/</code> session history</li><li><strong>Dashboard</strong>: Cache stats in context to avoid re-fetching on navigation</li><li><strong>Documentation</strong>: VitePress documentation site with guide, features, and API reference</li></ul><h3 id="fixed-8" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-8" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>CC Bridge</strong>: Prevent orphaned <code>tmux attach-session</code> processes from accumulating on server reload/crash via <code>PR_SET_PDEATHSIG</code> and startup cleanup</li><li><strong>CC Bridge</strong>: Fix terminal not rendering in React StrictMode due to race condition in async attach flow</li></ul><h2 id="_1-0-0-2026-01-22" tabindex="-1"><a href="https://github.com/adrirubio/claude-deck/releases/tag/v1.0.0" target="_blank" rel="noreferrer">1.0.0</a> - 2026-01-22 <a class="header-anchor" href="#_1-0-0-2026-01-22" aria-label="Permalink to &quot;[1.0.0] - 2026-01-22&quot;">​</a></h2><h3 id="added-9" tabindex="-1">Added <a class="header-anchor" href="#added-9" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Initial release of Claude Deck</li><li><strong>Dashboard</strong>: Overview of Claude Code configuration status and usage statistics</li><li><strong>MCP Server Management</strong>: Add, edit, remove, and configure MCP servers (global and project-scoped)</li><li><strong>Commands Management</strong>: Create and manage custom slash commands with argument support</li><li><strong>Plugins Management</strong>: Install, configure, and manage Claude Code plugins</li><li><strong>Hooks Management</strong>: Configure pre/post hooks for various Claude Code events</li><li><strong>Permissions Management</strong>: Manage allowed and denied permissions for tools</li><li><strong>Backup &amp; Restore</strong>: Full backup and restore functionality for all configurations</li><li><strong>Project Management</strong>: Support for project-specific configurations</li><li><strong>CLI Executor</strong>: Execute Claude CLI commands from the web interface</li><li><strong>Usage Tracking</strong>: Track and visualize API usage and costs</li></ul><h3 id="technical" tabindex="-1">Technical <a class="header-anchor" href="#technical" aria-label="Permalink to &quot;Technical&quot;">​</a></h3><ul><li>FastAPI backend with async SQLAlchemy and SQLite</li><li>React 18 frontend with TypeScript, Vite, and shadcn/ui</li><li>RESTful API at <code>/api/v1/</code></li><li>CORS configured for local development</li></ul>',102)])])}const p=t(i,[["render",s]]);export{g as __pageData,p as default};
